export interface HealthLog {
  systolic: number;
  diastolic: number;
  weightKg: number;
  symptoms: string[];
}

export function evaluateVitals(log: HealthLog) {
  const isElevated = log.systolic >= 140 || log.diastolic >= 90;
  return {
    status: isElevated ? 'attention_required' : 'stable',
    actionCode: isElevated ? 'TRIGGER_PROVIDER_UPLINK' : 'CONTINUE_ROUTINE'
  };
}

export const BranchStatusCard = ({ branch }) => {
    const isOperational = branch.status === 'operational';
    return (
        <div className="branch-card border border-glass">
            <span className={`pulse-dot ${isOperational ? 'online' : 'maintenance'}`} />
            <h4>{branch.name}</h4>
            <p>Status: {isOperational ? 'Active' : 'Pending Management Approval'}</p>
        </div>
    );
};

