import { useState } from 'react';

export const useChallengeProgress = (totalDays = 7) => {
  const [completedDays, setCompletedDays] = useState<number[]>([]);
  const toggleDayComplete = (day: number) => {
    setCompletedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };
  const isFullyComplete = completedDays.length === totalDays;
  return { completedDays, toggleDayComplete, isFullyComplete };
};

export async function executeAtomicSwap(payload: TransactionPayload): Promise<SwapResult> {
    const sessionToken = await validateSessionHandshake();
    if (!sessionToken) throw new SecurityError("Unauthorized signature attempt");
    return await blockchainProvider.commitAtomicTransaction(payload, sessionToken);
}

export function generateWhatsAppLink(cartItems, customer) {
    const cartText = cartItems.map(item => `- ${item.name} x${item.qty}`).join('%0A');
    const baseText = `Hi, I\'d like to order:%0A${cartText}%0A%0ADelivery to: ${customer.address}`;
    return `https://wa.me/2348123456789?text=${encodeURIComponent(baseText)}`;
}

export function calculateInvoice(items: InvoiceItem[]) {
    const subtotal = items.reduce((sum, item) => sum + (item.unitPrice * item.quantity), 0);
    const tax = subtotal * 0.075; // 7.5% Vat
    return { subtotal, tax, total: subtotal + tax };
}

export function addRenderJob(queue, asset) {
    return [...queue, {
        id: `job_${Date.now()}`,
        filename: asset.name,
        status: 'queued',
        progress: 0
    }];
}

export function filterGuides(guides: Guide[], query: string) {
    const cleanQuery = query.toLowerCase().trim();
    return guides.filter(g => 
        g.courseCode.toLowerCase().includes(cleanQuery) || 
        g.title.toLowerCase().includes(cleanQuery)
    );
}

export function checkBatteryState(sensor: IoTSensor) {
    const isCritical = sensor.batteryLevel <= 0.15;
    return {
        sensorId: sensor.id,
        level: sensor.batteryLevel,
        alertState: isCritical ? 'LOW_BATTERY_WARNING' : 'NOMINAL'
    };
}

export function addToBakeryCart(cart, item) {
    const exists = cart.find(i => i.id === item.id);
    if (exists) {
        return cart.map(i => i.id === item.id ? { ...i, qty: i.qty + 1 } : i);
    }
    return [...cart, { ...item, qty: 1 }];
}

export function updateCabinPosition(cabin, targetFloor) {
    const distance = targetFloor - cabin.currentFloor;
    if (Math.abs(distance) < 0.05) {
        return { ...cabin, currentFloor: targetFloor, motorState: 'idle' };
    }
    const direction = Math.sign(distance);
    return {
        ...cabin,
        currentFloor: cabin.currentFloor + (direction * 0.08),
        motorState: direction > 0 ? 'moving_up' : 'moving_down'
    };
}
